    schemeCitation: "Marking points quoted from the SEC marking scheme, Computer Science 2025 Ordinary Level — © State Examinations Commission.",
    id: "cs-2025-ol-q14-b-iv", topicId: "cs-2-2", conceptId: "describe-two-design-features-could-be",
    section: "B", questionRef: "2025 OL Q14(b)(iv)",
    stem: "The vending machine needs to be tested before it is released. Code entered Money inserted (€) Expected result B1 3 Oreos dispensed, €0.50 change given 1.2 Water dispensed, no change given C1 Error – not enough money inserted C2 0.75",
    questionText: "Describe two design features that could be incorporated into the vending machine to make it accessible to as many different types of users as possible.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 8,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Large Buttons: Easily readable buttons with high-contrast colours and tactile feedback can help users with visual impairments.", marks: null },
    { id: "r-2", kind: "point", verbatim: "Braille: Adding Braille next to each button and on product labels helps blind or low- vision users identify items and make selections.", marks: null },
    { id: "r-3", kind: "point", verbatim: "Audio: A voice-guided system could provide instructions, item names, and prices, which is helpful for visually impaired users.", marks: null },
    { id: "r-4", kind: "point", verbatim: "Height Position: A height-adjustable interface or lower panel allows both standing users and those in wheelchairs to access the machine comfortably.", marks: null },
    { id: "r-5", kind: "point", verbatim: "Touchscreen: A touchscreen interface with an accessibility mode that enlarges text, adds voice assistance, or reduces complexity for users with cognitive disabilities.", marks: null },
    { id: "r-6", kind: "point", verbatim: "Multi-Language Support: Providing instructions in multiple languages accommodates users who may not speak the primary language displayed on the machine.", marks: null },
    ],
